package com.smartcanteen.config;
import com.smartcanteen.domain.*; import com.smartcanteen.repo.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class SeedData { @Bean CommandLineRunner seed(UserRepository users,MenuRepository menus,PasswordEncoder encoder){return args->{if(users.count()==0){users.save(new User("student@campus.test","Student",encoder.encode("password"),User.Role.STUDENT));users.save(new User("staff@campus.test","Kitchen Staff",encoder.encode("password"),User.Role.STAFF));users.save(new User("admin@campus.test","Admin",encoder.encode("password"),User.Role.ADMIN));}if(menus.count()==0){menus.save(new MenuItem("Campus Masala Bowl","MEALS","Rice, lentils, roasted vegetables and a mint finish.","🍛",85));menus.save(new MenuItem("Paneer Kathi Roll","SNACKS","Smoky paneer, peppers and chutney in a warm wrap.","🌯",70));menus.save(new MenuItem("Cold Coffee","BEVERAGES","Chilled coffee with a light cocoa foam.","🧋",55));menus.save(new MenuItem("Mango Cheesecake","DESSERTS","Creamy cheesecake with fresh Alphonso mango.","🍰",95));menus.save(new MenuItem("Chilli Garlic Noodles","MEALS","Wok-tossed noodles with greens and sesame.","🍜",90));}};} }
